using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Windows.Forms;
namespace MacroExecute
{
    internal static class ClipboardRuleTests
    {
        internal const string Example="string1 string2 \"string 3\"\nAND\nstring2 \"string 3\" string4\nGROUP OR\nstring4 \"string 5\" string6\nAND\n\"string 5\" string6 string7";
        private static void Check(bool value,string message){if(!value)throw new Exception(message);}
        private static Step Rule(string text){return new Step{Kind=ActionKind.IfClipboard,ClipboardMatch=ClipboardMatchMode.Rules,Text=text};}
        private static IEnumerable<Control> All(Control root){foreach(Control c in root.Controls){yield return c;foreach(var child in All(c))yield return child;}}
        private static void Apply(StepEditor editor){typeof(StepEditor).GetMethod("Apply",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(editor,null);}
        private static int RightInForm(Control control){int x=control.Width;for(Control c=control;!(c is Form);c=c.Parent)x+=c.Left;return x;}
        public static void Run(Action<string,Action> test,string directory)
        {
            test("Optional reuse lets one literal string satisfy several AND clauses only in the chosen group",delegate{var step=Rule("word\nAND\n\"word\"\nGROUP OR\nother\nAND\n\"other\"");Check(!ClipboardCondition.Matches("word",step),"Default distinct rule changed");step.ClipboardReuseGroups=new[]{0};Check(ClipboardCondition.Matches("word",step)&&!ClipboardCondition.Matches("other",step),"Reuse leaked across groups");step.ClipboardReuseGroups=new[]{1};Check(!ClipboardCondition.Matches("word",step)&&ClipboardCondition.Matches("other",step),"Group setting not independent");});
            test("Reuse cannot replace missing requirements or combine partial groups",delegate{var step=Rule("shared x\nAND\nshared\nAND\nrequired\nGROUP OR\nother\nAND\nmissing");step.ClipboardReuseGroups=new[]{0,1};Check(!ClipboardCondition.Matches("shared other",step)&&ClipboardCondition.Matches("shared required",step),"Reuse skipped a required row");});
            test("Overlap detection compares parsed strings across AND clauses with configured casing",delegate{Check(ClipboardRules.SharedTerms(ClipboardRules.Parse("word \"two words\"\nAND\n\"word\" \"two words\"")[0],false).Length==2,"Quoted duplicates not recognized");Check(ClipboardRules.SharedTerms(ClipboardRules.Parse("word word\nOR\nword")[0],false).Length==0,"OR alternatives incorrectly enable AND reuse");Check(ClipboardRules.SharedTerms(ClipboardRules.Parse("word\nAND\nWORD")[0],false).Length==0&&ClipboardRules.SharedTerms(ClipboardRules.Parse("word\nAND\nWORD")[0],true).Length==1,"Ignore case not respected");});
            test("Conditional group checkboxes appear update and disappear without stealing row focus",delegate{using(var editor=new StepEditor(Rule("word\nAND\nother"),directory)){var builder=All(editor).OfType<ClipboardRuleBuilder>().Single();Check(builder.AvailableReuseOptions==0,"Checkbox shown without overlap");var inputs=All(builder).OfType<TextBox>().ToArray();inputs[1].Text="\"word\"";Check(builder.AvailableReuseOptions==1,"Checkbox missing for quoted duplicate");var option=All(builder).OfType<ThemeCheckBox>().Single(c=>c.AccessibleName=="Allow shared strings in clipboard group 1");option.Checked=true;Apply(editor);Check(editor.Value.ClipboardReuseGroups.SequenceEqual(new[]{0})&&ClipboardCondition.Matches("word",editor.Value),"Checkbox not saved");inputs[1].Text="WORD";Check(builder.AvailableReuseOptions==0&&builder.ReuseGroups.Length==0,"Stale reuse option retained");builder.IgnoreCase=true;Check(builder.AvailableReuseOptions==1,"Case change did not refresh options");inputs[1].Text="\"unfinished";inputs[1].Text="word";Check(builder.AvailableReuseOptions==1&&!editor.Visible,"Editing quotes broke builder");}using(var legacy=new StepEditor(new Step{Kind=ActionKind.IfClipboard,ClipboardMatch=ClipboardMatchMode.All,Text="word\nword"},directory)){var choice=All(legacy).OfType<ThemeCheckBox>().Single(c=>c.AccessibleName=="Allow shared strings in clipboard group 1");choice.Checked=true;choice.Checked=false;Apply(legacy);Check(legacy.Value.ClipboardMatch==ClipboardMatchMode.Rules&&!ClipboardCondition.Matches("word",legacy.Value),"Explicit reuse edit reverted to legacy behavior");}});
            test("Group insertion and removal keep reuse choices attached to the original group",delegate{using(var b=new ClipboardRuleBuilder("a\nAND\na\nGROUP OR\nb\nAND\nb",new[]{1})){b.Insert(1,"GROUP OR");All(b).OfType<TextBox>().ElementAt(2).Text="new";Check(b.ReuseGroups.SequenceEqual(new[]{2}),"Insertion moved choice to wrong group");b.Remove(2);Check(b.ReuseGroups.SequenceEqual(new[]{1}),"Removing another group lost choice");b.Remove(2);Check(b.ReuseGroups.Length==0,"Removed overlap still allows reuse");}});
            test("Reuse settings survive workflow and player roundtrips and clone without shared mutable arrays",delegate{var step=Rule("a\nAND\na");step.ClipboardReuseGroups=new[]{0};var copy=step.Clone();copy.ClipboardReuseGroups[0]=1;Check(step.ClipboardReuseGroups[0]==0,"Clone aliases reuse flags");var macro=new Macro{Steps=new List<Step>{step}};var loaded=Storage.Decode(Storage.Encode(macro));Check(ClipboardCondition.Matches("a",loaded.Steps[0]),"JSON lost reuse setting");string file=Path.Combine(directory,"reuse-player.exe");Portable.Export(System.Reflection.Assembly.GetExecutingAssembly().Location,file,macro);Check(Portable.Read(file).Steps[0].ClipboardReuseGroups.SequenceEqual(new[]{0}),"Export lost choice");foreach(var indexes in new[]{new[]{-1},new[]{1},new[]{0,0},null}){step.ClipboardReuseGroups=indexes;bool rejected=false;try{ClipboardCondition.Validate(step);}catch(InvalidDataException){rejected=true;}Check(rejected,"Malformed group choices accepted");}});
            test("Quoted row rules satisfy the requested truth table without reusing a matching string",delegate{var step=Rule(Example);foreach(string text in new[]{"string1 string2","string4 string 5","string1 string 3","string6 string7"})Check(ClipboardCondition.Matches(text,step),"Expected complete group: "+text);foreach(string text in new[]{"string2","string 3","string6","string1 string 5","string1","unrelated"})Check(!ClipboardCondition.Matches(text,step),"Unexpected incomplete group: "+text);});
            test("Matching finds a distinct assignment rather than greedily consuming alternatives",delegate{Check(ClipboardCondition.Matches("a b c",Rule("a b\nAND\na\nAND\nb c")),"Did not reassign first row to b or c");Check(!ClipboardCondition.Matches("a b",Rule("a b\nAND\na\nAND\nb")),"Reused a matching string");});
            test("Repeated alternatives case folding NOT and empty clipboard obey rule contracts",delegate{var step=Rule("same same\nAND\nSAME");step.ClipboardIgnoreCase=true;Check(!ClipboardCondition.Matches("same",step),"Case variants count as distinct strings");step.ClipboardNegate=true;Check(ClipboardCondition.Matches("same",step)&&!ClipboardCondition.Matches(null,step)&&!ClipboardCondition.Matches("",step),"NOT or empty contract changed");});
            test("Quoted phrases spaces literal quotes and backslashes tokenize safely",delegate{string[] values={"word","string 3","a\"b","C:\\Path With Spaces\\file.txt","AND","GROUP OR"};string expression=string.Join(" ",values.Select(ClipboardRules.Quote));Check(ClipboardRules.Terms(expression).SequenceEqual(values),"Quoted literal roundtrip failed");Check(ClipboardRules.Terms("word1\t\"word 2\" word3").SequenceEqual(new[]{"word1","word 2","word3"}),"Mixed quoted and bare terms failed");Check(!ClipboardCondition.Matches("word 2",Rule("\"word 2 word3\"")),"Quoted phrase split");});
            test("OR rows merge alternatives within an AND clause without crossing group boundaries",delegate{var rule=Rule("red\nOR\nblue green\nAND\nround\nGROUP OR\nsquare\nAND\nyellow");Check(ClipboardCondition.Matches("blue round",rule)&&ClipboardCondition.Matches("square yellow",rule),"OR row not joined");Check(!ClipboardCondition.Matches("red yellow",rule),"Partial groups mixed");});
            test("Malformed quotes empty terms dangling connectors and oversized rules are rejected",delegate{foreach(string text in new[]{"","\"\"","\"open","bare\"quote","\"phrase\"suffix","AND\na","a\nAND","a\nAND\nOR\nb","a\nb",string.Join(" ",Enumerable.Repeat("x",129))}){bool rejected=false;try{ClipboardCondition.Validate(Rule(text));}catch(InvalidDataException){rejected=true;}Check(rejected,"Accepted invalid rule: "+text);}ClipboardCondition.Validate(Rule(string.Join(" ",Enumerable.Range(0,128).Select(i=>"term"+i))));});
            test("Rule workflow clone and exported player preserve the expression and match mode",delegate{var macro=new Macro{Steps=new List<Step>{Rule(Example)}};var decoded=Storage.Decode(Storage.Encode(macro));Check(decoded.Steps[0].Clone().Text==Example&&decoded.Steps[0].ClipboardMatch==ClipboardMatchMode.Rules,"Rule serialization lost");string file=Path.Combine(directory,"row-rules-player.exe");Portable.Export(System.Reflection.Assembly.GetExecutingAssembly().Location,file,macro);Check(Portable.Read(file).Steps[0].ClipboardMatch==ClipboardMatchMode.Rules,"Player lost rules");});
            test("Legacy strings keep literal spaces and remain unchanged when opening the row editor",delegate{foreach(var mode in new[]{ClipboardMatchMode.Any,ClipboardMatchMode.All,ClipboardMatchMode.Groups})using(var editor=new StepEditor(new Step{Kind=ActionKind.IfClipboard,ClipboardMatch=mode,Text="Monthly Report\nStatus: Approved"},directory)){var builder=All(editor).OfType<ClipboardRuleBuilder>().Single();Check(builder.Expression.Contains("\"Monthly Report\""),"Legacy phrase was split into OR words");Apply(editor);Check(editor.Value.ClipboardMatch==mode&&editor.Value.Text=="Monthly Report\nStatus: Approved","Untouched legacy behavior changed");}});
            test("Rule builder adds removes and saves rows and updates height without showing a window",delegate{using(var editor=new StepEditor(Rule("alpha"),directory)){var builder=All(editor).OfType<ClipboardRuleBuilder>().Single();int initial=builder.ContentHeight;builder.Insert(0,"AND");var inputs=All(builder).OfType<TextBox>().ToArray();inputs[1].Text="beta \"gamma delta\"";Check(builder.ContentHeight>initial,"Builder did not expand");Apply(editor);Check(ClipboardCondition.Matches("alpha beta",editor.Value),"Edited rows not applied");builder.Insert(1,"GROUP OR");All(builder).OfType<TextBox>().Last().Text="epsilon";Apply(editor);Check(ClipboardCondition.Matches("epsilon",editor.Value),"New alternative group lost");builder.Remove(1);Apply(editor);Check(builder.Expression=="alpha\nGROUP OR\nepsilon"&&!editor.Visible,"Remove damaged grouping or opened UI");}});
            test("Saved OR rows merge into space alternatives without changing group semantics",delegate{using(var b=new ClipboardRuleBuilder("a\nAND\nb\nOR\nc\nGROUP OR\nd\nAND\ne")){Check(b.Expression=="a\nAND\nb c\nGROUP OR\nd\nAND\ne","Saved OR rows were not simplified");Check(ClipboardCondition.Matches("a c",Rule(b.Expression)),"Merged alternatives changed meaning");b.Remove(2);Check(b.Expression=="a\nAND\nb c\nGROUP OR\ne","Group boundary lost");}});
            test("Clipboard row builder renders in compact and full layouts for all six palettes",delegate{foreach(string style in UiTheme.Styles)foreach(bool dark in new[]{true,false}){UiTheme.Style=style;UiTheme.Dark=dark;using(var editor=new StepEditor(Rule(Example),directory)){HeadlessUi.Render(editor,Path.Combine(directory,"rules-"+style+"-"+dark+".png"));editor.Size=editor.MinimumSize;HeadlessUi.Render(editor,Path.Combine(directory,"rules-compact-"+style+"-"+dark+".png"));var builder=All(editor).OfType<ClipboardRuleBuilder>().Single();Check(builder.Controls[0].Width<=builder.ClientSize.Width&&builder.Right<=builder.Parent.ClientSize.Width,"Rule rows overflow the viewport");foreach(var button in All(builder).OfType<ThemeButton>())Check(button.Right<=button.Parent.ClientSize.Width,"Rule buttons are clipped");Check(RightInForm(All(builder).OfType<ThemeButton>().First())<=editor.ClientSize.Width,"Row controls extend outside the window");Check(RightInForm(All(editor).OfType<Button>().Single(b=>b.Text=="Save step"))<=editor.ClientSize.Width,"Save step is outside the window");Check(!editor.Visible,"Rules editor became visible");}}UiTheme.Style="Aftershock";UiTheme.Dark=true;});
        }
    }
}
